import React from 'react';
import InteractiveSeating from './components/InteractiveSeating';
import GateSimulator from './components/GateSimulator';

function App() {
  return (
    <div style={{ padding: '40px', fontFamily: 'sans-serif' }}>
      <h1>Smart Ticketing Platform</h1>
      <p>Select an available seat to lock it for checkout:</p>
      <InteractiveSeating eventId={1} />
      
      <hr style={{ margin: '40px 0' }} />
      
      <GateSimulator />
    </div>
  );
}

export default App;
